CaseInvBitmapTextRatio=21/45

local function createFontTexture()
    if not file.Exists("caseinv/font.png", "DATA") then
        if not file.IsDir("caseinv", "DATA") then
            file.CreateDir("caseinv", "DATA")
        end
        local dat = util.Base64Decode(_font)

        file.Write("caseinv/font.png", dat)
    end

    fontMat = Material( "data/caseinv/font.png", "noclamp smooth ignorez" )
end

---Sick ass bitmap font drawing
---Here because gmod doesn't let you scale text/fonts
---@param text string
---@param x number?
---@param y number?
---@param height number?
function CaseInvBitmapTextDraw(text, x, y, height)
    x = x or 0
    y = y or 0
    height = height or 45
    local scaleW, scaleH = _CaseUIGetScaledDiff()
    if fontMat == nil then
        createFontTexture()
    end

    surface.SetMaterial(fontMat)
    local _height = height*scaleH
    local width = (height*CaseInvBitmapTextRatio)*scaleW
    local curChar = 0

    for i = 1, #text do
        local c = text:sub(i,i)
        local chr = fontInfo[tostring(string.byte(c))]
        if chr == nil then
            chr = fontInfo[tostring(string.byte("?"))]
        end
        local UVX = chr.x / fontInfo.W
        local UVY = chr.y / fontInfo.H
        surface.DrawTexturedRectUV( x + curChar*width, y, width, _height, UVX, UVY, UVX + (chr.width / fontInfo.W), UVY + (chr.height / fontInfo.H ))
        curChar = curChar + 1
    end


end

---god bless monospace<br>
--- Returns the size of text in pixels (comes scaled for your pleasure)
---@param text string
---@param height number
function CaseInvBitmapTextSize(text, height)
    local scaleW, scaleH = _CaseUIGetScaledDiff()
    local _height = height*scaleH
    local width = (height*CaseInvBitmapTextRatio)*scaleW

    return #text*width,_height
end

